import{_ as t,o as _,c as a,ac as p}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"党的十一届七中全会给刘伯承同志的致敬信","description":"","frontmatter":{"prev":{"text":"[报道]十一届七中全会发表公报 我党第十二次全国代表大会九月一日召开","link":"./十一届七中全会发表公报 我党第十二次全国代表大会九月一日召开"},"next":{"text":"党的十一届七中全会给蔡畅同志的致敬信","link":"./党的十一届七中全会给蔡畅同志的致敬信"}},"headers":[],"relativePath":"11/7/党的十一届七中全会给刘伯承同志的致敬信.md","filePath":"11/7/党的十一届七中全会给刘伯承同志的致敬信.md"}'),r={name:"11/7/党的十一届七中全会给刘伯承同志的致敬信.md"};function s(n,e,o,i,c,d){return _(),a("div",null,[...e[0]||(e[0]=[p('<h1 id="党的十一届七中全会给刘伯承同志的致敬信" tabindex="-1">党的十一届七中全会给刘伯承同志的致敬信 <a class="header-anchor" href="#党的十一届七中全会给刘伯承同志的致敬信" aria-label="Permalink to &quot;党的十一届七中全会给刘伯承同志的致敬信&quot;">​</a></h1><p><em>（一九八二年八月六日）</em></p><p>敬爱的刘伯承同志：</p><p>  我们，正在举行中国共产党第十一届中央委员会第七次全体会议的同志，谨以全会的名义，向您致以亲切的问候和崇高的敬意！</p><p>  从一九四五年在延安召开党的第七次全国代表大会以来，您是历次党代表大会的代表，都当选为中央委员会委员。由于年龄和健康状况，您不能再参加即将召开的党的第十二次全国代表大会，也不能再继续担任党和国家的领导职务。您对中国革命的贡献和崇高的品德，将为我们全党所永远怀念和敬佩。</p><p>  您在青年时代就投身于辛亥革命和反对北洋军阀的战争，就是一位英勇善战的爱国军人。在党的领导下，您发动四川泸（州）顺（庆）起义，又参与发动和领导南昌起义，您是中国人民解放军的缔造者之一。土地革命战争时期，在反“围剿”战争和二万五千里长征中，您作为中央军委总参谋长，迭挫强敌，战功卓著，并同张国焘的分裂活动进行了坚决斗争。抗日战争时期，您转战华北敌后，发展人民游击战争，是创建晋冀鲁豫根据地主要领导人之一。解放战争时期，您正确执行党中央的军事部署，在一九四七年率领十万大军渡过黄河，挺进中原，构成了我军战略反攻的光辉篇章。您在一系列重要战役中，特别是在上党、平汉、淮海、渡江战役中，在进军解放西南战役中，表现出了卓越的军事才能。您为战胜日本帝国主义，打败国民党反动派，创建中华人民共和国，建立了不朽功勋。建国以后，您为培养我军的高级指挥干部付出了辛勤劳动，为建设现代化、正规化的革命军队作出了新的重大贡献。您的指挥艺术和作战谋略是毛泽东军事思想的重要组成部分。您不愧是身经百战的元帅，马克思主义的军事理论家，坚强的无产阶级革命家。</p><p>  您忠于祖国，忠于人民，忠于共产主义事业。十年内乱期间，您身患重病，仍关心党和国家安危。您勤奋学习，严守纪律，从不居功自傲。您艰苦奋斗，廉洁奉公，先天下之忧而忧，后天下之乐而乐，与人民群众和士兵同呼吸，共命运。您的高尚品德，在党内外深孚众望。全党、全军和全国各族人民一定永远铭记您的功绩，您永远是我们的学习榜样。</p><p>  我们党即将举行的第十二次全国代表大会将在马克思列宁主义和毛泽东思想指导下，总结经验，制定实现新时期任务的方针和措施；通过新的党章；选举新的中央委员会，使我们党中央成为更加朝气蓬勃的战斗指挥部，领导全国人民为全面开创社会主义现代化建设的新局面而努力奋斗。毫无疑问，老一辈无产阶级革命家艰难缔造的事业必将得到新的发展。这是我们可以向您保证和告慰的。</p><p>  衷心祝愿您长寿！</p><div class="sig-block-b"><div class="text-center"><p><strong>中国共产党第十一届<br>中央委员会第七次全体会议</strong><br> 一九八二年八月六日</p></div></div>',10)])])}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
